// ✅ Bản vá: dữ liệu 'tươi đúng hạn', focus chỉ refetch chỗ thật sự cần
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 60_000,           // ✅ 1 phút coi là đủ mới
      gcTime: 5 * 60_000,          // dọn cache chết sau 5 phút
      refetchOnWindowFocus: false, // ✅ tắt mặc định — chống flood
      retry: (failureCount, error) => {
        const status = (error as { status?: number }).status;
        if (status === 429 || status === 403) return false; // đừng đấm API đang nổi điên
        return failureCount < 2;
      },
    },
  },
});

// Query nóng (thông báo, bảng giá) MỚI được bật focus-refetch có chủ đích
function Notifications() {
  useQuery({
    queryKey: ['notifications'],
    queryFn: fetchNotifications,
    staleTime: 10_000,
    refetchOnWindowFocus: true, // ✅ chọn lọc từng query, không bắn đại
  });
}

