// 1) Query Key Factory — nguồn sự thật duy nhất cho mọi key
export const postKeys = {
  all: ['posts'] as const,
  lists: () => [...postKeys.all, 'list'] as const,
  list: (params: { page: number; role?: string }) =>
    [...postKeys.lists(), params] as const, // ✅ object được hash ổn định
  details: () => [...postKeys.all, 'detail'] as const,
  detail: (id: string) => [...postKeys.details(), id] as const,
};

// 2) Component luôn gọi factory — cấm hardcode key rời rạc
function PostList({ page }: { page: number }) {
  const { data } = useQuery({
    queryKey: postKeys.list({ page, role: currentUser.role }),
    queryFn: () => fetchPosts({ page, role: currentUser.role }),
  });
}

// 3) Invalidate đúng phạm vi: làm mới mọi list nhưng không trúng detail
queryClient.invalidateQueries({ queryKey: postKeys.lists() });

