// ✅ Mutation xong phải 'thông báo' cho cache — chain chuẩn v5
import { useMutation, useQueryClient } from '@tanstack/react-query';

export function useDeletePost() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: string) => api.delete(`/posts/${id}`),

    onSuccess: (_data, id) => {
      // 1) Dọn detail khỏi cache — không còn hồn ma để hồi sinh
      queryClient.removeQueries({ queryKey: postKeys.detail(id) });
      // 2) Mọi list chứa nó thành stale → refetch nền tự chạy
      queryClient.invalidateQueries({ queryKey: postKeys.lists() });
    },

    onError: () => toast.error('Xoá thất bại — dữ liệu giữ nguyên'),
  });
}

